const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');const pw=require('playwright');
const engine=process.env.CORAL_ENGINE||'chromium',out=process.env.CORAL_OUT||'coral-qa',base=process.env.CORAL_URL||'http://127.0.0.1:8765/coral-mother-core-seed-r01/growth-lab-r01/';fs.mkdirSync(out,{recursive:true});
(async()=>{let browser=await pw[engine].launch({headless:true});const ctx=await browser.newContext({viewport:{width:1440,height:1000},deviceScaleFactor:1});await ctx.tracing.start({screenshots:true,snapshots:true});let page=await ctx.newPage();let errors=[],checks=[],states=[];page.on('pageerror',e=>errors.push(String(e)));page.on('response',r=>{if(r.status()>=400)errors.push(`${r.status()} ${r.url()}`)});
async function ready(){await page.waitForFunction(()=>window.__CORAL_GROWTH__?.complete&&window.__CORAL_GROWTH__?.compiled,null,{timeout:180000});await page.waitForTimeout(150);}
async function snap(name){await page.screenshot({path:path.join(out,name+'.png'),fullPage:false});let s=await page.evaluate(()=>({state:window.__CORAL_GROWTH__,audit:window.__CORAL_AUDIT__()}));assert.equal(s.audit.glError,0);assert(s.audit.uniqueColors>50,'Actual shader has visible varied pixels');assert(s.audit.opaqueSamples>100,'Actual nonempty geometry');assert(s.state.vertices>100);states.push({name,...s});checks.push({name,passed:true});return s;}
async function timeline(value){await page.locator('#timeline').evaluate((e,v)=>{e.value=v;e.dispatchEvent(new Event('input',{bubbles:true}));},value);await page.waitForTimeout(80);}
try{
await page.goto(base,{waitUntil:'networkidle'});await ready();assert.match(await page.title(),/珊瑚生长实验/);assert.equal(await page.locator('video').count(),0);assert.equal(await page.locator('iframe').count(),0);const initial=await snap('01-default-desktop');assert.equal(initial.state.frame,90);assert.equal(initial.state.version,"CORAL-GROWTH-R02-20261007");
await timeline(0);let zero=await snap('02-initial-tissue');await timeline(90);let middle=await snap('03-growth-090');await timeline(180);let grown=await snap('04-growth-180');assert(grown.state.vertices>zero.state.vertices);assert.notEqual(grown.state.geometryFingerprint,zero.state.geometryFingerprint);
await page.locator('#restart').click();await page.locator('#play').click();await page.waitForTimeout(900);await page.locator('#play').click();let paused=await page.evaluate(()=>window.__CORAL_GROWTH__.frame);await page.waitForTimeout(400);assert.equal(await page.evaluate(()=>window.__CORAL_GROWTH__.frame),paused);assert(paused>0);checks.push({name:'Play advances and pause holds solved frame',passed:true});
await timeline(150);const canvas=page.locator('#view'),box=await canvas.boundingBox();await page.mouse.move(box.x+box.width*.55,box.y+box.height*.5);await page.mouse.down();await page.mouse.move(box.x+box.width*.7,box.y+box.height*.56,{steps:15});await page.mouse.up();await page.mouse.wheel(0,-370);await snap('05-rotated-closeup');assert((await page.evaluate(()=>window.__CORAL_GROWTH__.cameraChanges))>0);await page.locator('#homeCamera').click();
for(const m of ['neutral','curvature','direction','shadow']){await page.locator(`[data-mask="${m}"]`).click();let s=await snap('06-mask-'+m);assert.equal(s.state.view,m);}await page.locator('[data-mask="material"]').click();await page.locator('#wireframe').click();await snap('07-wireframe');assert.equal(await page.locator('#wireframe').getAttribute('aria-pressed'),'true');await page.locator('#wireframe').click();
await timeline(90);let previous=await page.evaluate(()=>window.__CORAL_GROWTH__.geometryFingerprint);await page.locator('#seed').fill('18');await page.locator('#regenerate').click();await ready();let changed=await snap('08-new-seed');assert.notEqual(changed.state.geometryFingerprint,previous);assert.equal(changed.state.parameters.seed,18);
await page.locator('#shadow').evaluate(e=>{e.value=0;e.dispatchEvent(new Event('input',{bubbles:true}));});await page.locator('#regenerate').click();await ready();let changedMask=await snap('09-no-shadow-recomputed');assert.equal(changedMask.state.parameters.shadow,0);assert.notEqual(changedMask.state.geometryFingerprint,changed.state.geometryFingerprint);
await page.locator('#direction').evaluate(e=>{e.value=.95;e.dispatchEvent(new Event('input',{bubbles:true}));});await page.locator('#regenerate').click();await ready();await snap('10-direction-recomputed');await timeline(180);await page.locator('[data-mask="neutral"]').click();await snap('11-neutral-final');await page.locator('[data-mask="material"]').click();
await page.locator('#aboutOpen').click();assert(await page.locator('#about').isVisible());await page.keyboard.press('Escape');assert(!await page.locator('#about').isVisible());await page.locator('#aboutOpen').click();await page.locator('#aboutClose').click();assert(!await page.locator('#about').isVisible());checks.push({name:'Source dialog opens, Escape and Close dismiss',passed:true});
const dlPromise=page.waitForEvent('download');await page.locator('#export').click();const dl=await dlPromise;await dl.saveAs(path.join(out,'computed-coral.obj'));let obj=fs.readFileSync(path.join(out,'computed-coral.obj'),'utf8');assert(obj.includes('\nv '));assert(obj.includes('\nf '));assert(obj.includes('Iteration'));checks.push({name:'Actual current mesh OBJ export',passed:true});
await page.setViewportSize({width:390,height:844});await page.waitForTimeout(180);assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await page.screenshot({path:path.join(out,'12-mobile-viewport.png'),fullPage:true});await page.locator('#regenerate').scrollIntoViewIfNeeded();await page.locator('#regenerate').click();await ready();await page.locator('#viewport').scrollIntoViewIfNeeded();await snap('13-mobile-recomputed');
await page.setViewportSize({width:1440,height:1000});await page.locator('.back').click();await page.waitForURL('**/coral-mother-core-seed-r01/');assert.match(await page.title(),/Coral Mother/);await page.goBack({waitUntil:'domcontentloaded'});await ready();await snap('14-return-reopened');
assert.deepEqual(errors,[]);assert.deepEqual(await page.evaluate(()=>window.__CORAL_GROWTH__.errors),[]);await ctx.tracing.stop({path:path.join(out,'trace.zip')});fs.writeFileSync(path.join(out,'result.json'),JSON.stringify({passed:true,engine,browserVersion:browser.version(),url:base,actualPhoneTested:false,houdiniCookTested:false,checks,states,errors},null,2));console.log(JSON.stringify({passed:true,engine,checks:checks.length}));
}catch(e){await page.screenshot({path:path.join(out,'failure.png'),fullPage:true}).catch(()=>{});fs.writeFileSync(path.join(out,'failure.json'),JSON.stringify({error:String(e.stack||e),errors,states,checks},null,2));await ctx.tracing.stop({path:path.join(out,'trace.zip')}).catch(()=>{});throw e;}finally{await browser.close();}
})().catch(e=>{console.error(e);process.exit(1)});
